mapper.select:
SELECT id          AS "fileId",
       file_name   AS "fileName",
       created_at  AS "arrivalTime",
       storage_path AS "storagePath",
       biz_date    AS "bizDate",
       metadata_json ->> 'fileGroupCode' AS "fileGroupCode"
  FROM batch.file_record file
 WHERE file.tenant_id = #{tenantId}
   AND file.file_category = 'INPUT'
   AND file.file_name LIKE #{namePattern}
   AND file.created_at >= #{since}

   AND file.biz_date = #{bizDate}


   AND file.metadata_json ->> 'fileGroupCode' = #{fileGroupCode}


   AND file.metadata_json ->> 'arrivalState' = 'TRIGGERED'
   AND (
     NOT jsonb_exists(file.metadata_json, 'bundleWorkflowCode')
     OR EXISTS (
       SELECT 1
         FROM batch.workflow_definition target
        WHERE target.tenant_id = file.tenant_id
          AND target.id = #{workflowDefinitionId}
          AND target.workflow_code = file.metadata_json ->> 'bundleWorkflowCode'
     )
   )


   AND file.source_type = #{sourceType}

 ORDER BY file.created_at DESC, file.id DESC
 LIMIT 1

SELECT id          AS "fileId",
       file_name   AS "fileName",
       created_at  AS "arrivalTime"
  FROM batch.file_record
 WHERE tenant_id = #{tenantId}
   AND file_category = 'INPUT'
   AND file_name LIKE #{namePattern}
 ORDER BY created_at DESC, id DESC
 LIMIT #{limit}
